ADD MAP FLERETNM VERSION 1
    DEVICE IS 3270 SIZE IS 24 BY 80
    RECORDS ARE FLEWORK EMPLOYEE VEHICLE ASSIGNMENT
    .
    LITERAL 'FLERETN'                      ROW 1  COLUMN 2  INTENSITY BRIGHT.
    LITERAL 'COMPANY CAR RETURN'           ROW 1  COLUMN 31 INTENSITY BRIGHT.
    LITERAL 'VEHICLE ID'                   ROW 4  COLUMN 2.
    FIELD WK-VEHID                         ROW 4  COLUMN 16 LENGTH 8 UNPROTECTED.
    FIELD VH-PLATE                         ROW 4  COLUMN 28 LENGTH 8  PROTECTED.
    LITERAL 'HELD BY'                      ROW 6  COLUMN 2.
    FIELD EM-EMPID                         ROW 6  COLUMN 16 LENGTH 8  PROTECTED.
    FIELD EM-SURN                          ROW 6  COLUMN 28 LENGTH 20 PROTECTED.
    LITERAL 'SINCE'                        ROW 7  COLUMN 2.
    FIELD AS-STRT                          ROW 7  COLUMN 16 LENGTH 8  PROTECTED.
    LITERAL 'RETURN DATE'                  ROW 10 COLUMN 2.
    FIELD WK-RETDT                         ROW 10 COLUMN 16 LENGTH 8 UNPROTECTED
        EDIT PICTURE IS 9(8) REQUIRED.
    LITERAL 'ODOMETER'                     ROW 11 COLUMN 2.
    FIELD WK-ODO                           ROW 11 COLUMN 16 LENGTH 6 UNPROTECTED.
    FIELD WK-MSG                           ROW 22 COLUMN 2  LENGTH 60 PROTECTED.
    LITERAL 'ENTER=RETURN  PF3=MENU'       ROW 24 COLUMN 2.
